let savedWorkflows=[];try{savedWorkflows=JSON.parse(localStorage.getItem('runable-custom-workflows')||'[]').filter(w=>Array.isArray(w)&&w.length===6&&Array.isArray(w[5]));}catch{}
workflows.push(...savedWorkflows);
let category='All',query='',expanded=false;
const grid=document.querySelector('#workflow-grid');
function safe(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const categoryLabels={"Ads and marketing videos": "Ads and marketing videos", "Career": "Career", "Cast yourself": "Cast yourself", "Creative": "Creative", "Engineering": "Engineering", "Everyday videos": "Everyday videos", "Faceless videos": "Faceless videos", "Finance": "Finance", "Generative films": "Generative films", "Investments": "Investments", "Legal": "Legal", "Marketing": "Marketing", "Media": "Media", "Operations": "Operations", "Productivity": "Productivity", "Recruiting": "Recruiting", "Research": "Research", "Sales": "Sales", "Support": "Support", "UGC ads": "UGC ads", "Utility": "Utility", "Writing": "Writing", "Custom": "Your workflows"};
const libraryIcons={Create:'M4 4h16v16H4z M8 4v16 M4 9h16 M4 15h16',Research:'M10.5 17a6.5 6.5 0 1 0 0-13 6.5 6.5 0 0 0 0 13 M16 16l5 5',Grow:'M4 19V5 M4 19h16 M7 14l4-4 4 2 5-7',Organize:'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h5',Custom:'M5 5h5v5H5z M14 14h5v5h-5z M10 7h7v7'};
const expandedGroups=new Set();
function render(){
 const matches=workflows.map((w,i)=>({w,i})).filter(({w})=>(category==='All'||w[1]===category)&&w.join(' ').toLowerCase().includes(query));
 const groups=[...new Set(matches.map(({w})=>w[1]))];
 grid.innerHTML=groups.map(group=>{
  const entries=matches.filter(({w})=>w[1]===group),shown=expandedGroups.has(group)?entries:entries.slice(0,6);
  return `<section class="catalog-group"><div class="catalog-group-heading"><h3>${safe(categoryLabels[group]||group)}</h3>${entries.length>6?`<button type="button" data-expand="${safe(group)}">${expandedGroups.has(group)?'Show less':'See all'}</button>`:''}</div><div class="catalog-items">${shown.map(({w,i})=>{
   const icon=w[7]?`<span class="catalog-original-icon" style="mask-image:url('${safe(w[7])}');-webkit-mask-image:url('${safe(w[7])}')"></span>`:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4"><path d="${libraryIcons.Custom}"/></svg>`;
   const content=`<span class="catalog-icon" aria-hidden="true">${icon}</span><span class="catalog-copy"><span class="catalog-title">${safe(w[0])}</span><span class="catalog-description">${safe(w[2])}</span></span>`;
   return w[6]?`<a class="catalog-item" href="${safe(w[6])}">${content}</a>`:`<button class="catalog-item" data-index="${i}" aria-label="Preview ${safe(w[0])}">${content}</button>`;
  }).join('')}</div></section>`;
 }).join('');
 document.querySelector('#result-count').textContent=`${matches.length} workflows`;
 document.querySelector('#no-results').hidden=!!matches.length;
 document.querySelector('#show-more').hidden=true;
}
grid.addEventListener('click',e=>{const button=e.target.closest('[data-expand]');if(!button)return;const group=button.dataset.expand;expandedGroups.has(group)?expandedGroups.delete(group):expandedGroups.add(group);render()});
document.querySelector('#search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();render()});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});render()}));document.querySelector('#show-more').addEventListener('click',()=>{expanded=true;render()});
const dialog=document.querySelector('#detail');grid.addEventListener('click',e=>{const b=e.target.closest('[data-index]');if(!b)return;const w=workflows[Number(b.dataset.index)];document.querySelector('#detail-title').textContent=w[0];document.querySelector('#detail-category').textContent=w[1].toUpperCase();document.querySelector('#detail-description').textContent=w[2];document.querySelector('#detail-needs').textContent=w[4];document.querySelector('#detail-output').textContent=w[3];document.querySelector('#detail-steps').innerHTML=w[5].map(s=>`<li>${safe(s)}</li>`).join('');dialog.showModal()});document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});

const workflowPrompt = document.querySelector('#plugin-prompt');
const workflowExample = document.querySelector('#sample-prompt');
const samplePrompts = [
 'Create a workflow that researches a company and prepares a brief before every sales call.',
 'Create a workflow that turns a product link into a video ad, a caption, and an email draft.',
 'Create a workflow that summarizes new customer feedback and sends the key themes to Slack.',
 'Create a workflow that gathers project updates and drafts a weekly team newsletter.'
];
let sampleIndex=0, letter=0, exampleTimer;
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
function stopExample(){clearTimeout(exampleTimer)}
function showExample(){
 stopExample();
 if(document.activeElement===workflowPrompt || workflowPrompt.textContent || document.hidden)return;
 workflowExample.hidden=false;workflowPrompt.classList.add("showing-sample");
 if(reducedMotion.matches){workflowExample.textContent=samplePrompts[0];return}
 workflowExample.textContent=samplePrompts[sampleIndex].slice(0,letter++);
 if(letter>samplePrompts[sampleIndex].length){
  exampleTimer=setTimeout(()=>{sampleIndex=(sampleIndex+1)%samplePrompts.length;letter=0;showExample()},2600);
 }else exampleTimer=setTimeout(showExample,32);
}
workflowPrompt.addEventListener('focus',()=>{stopExample();workflowExample.hidden=true;workflowPrompt.classList.remove('showing-sample');workflowPrompt.dataset.placeholder='Describe what you want your workflow to do…'});
workflowPrompt.addEventListener('blur',()=>{workflowPrompt.dataset.placeholder='';if(!workflowPrompt.textContent){letter=0;showExample()}});
workflowPrompt.addEventListener('input',()=>{workflowPrompt.classList.toggle('has-content',!!workflowPrompt.textContent.trim());document.querySelector('#workflow-feedback').textContent=''});
document.querySelector('#workflow-composer').addEventListener('submit',e=>{
 e.preventDefault();
 if(!workflowPrompt.textContent.trim()) {workflowPrompt.focus();return}
 openWorkflowBuilder(workflowPrompt.textContent.trim());
});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopExample();else showExample()});
reducedMotion.addEventListener('change',showExample);
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!document.activeElement.isContentEditable&&!dialog.open&&!document.querySelector('#workflow-builder').open){e.preventDefault();document.querySelector('#search').focus()}});
showExample();render();

// Same source and effective speed as the Plugins hero (0.025× original).
const workflowBgVideo=document.querySelector('#workflow-bg-video');
if(workflowBgVideo){
 workflowBgVideo.defaultPlaybackRate=.25;
 workflowBgVideo.playbackRate=.25;
 const syncVideo=()=>{if(document.hidden||reducedMotion.matches)workflowBgVideo.pause();else workflowBgVideo.play().catch(()=>{})};
 document.addEventListener('visibilitychange',syncVideo);
 reducedMotion.addEventListener('change',syncVideo);
 new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)syncVideo();else workflowBgVideo.pause()})}).observe(workflowBgVideo);
 syncVideo();
}

const builder=document.querySelector('#workflow-builder');
function addBuilderStep(value=''){
 const row=document.createElement('div');row.className='builder-step';
 const input=document.createElement('input');input.required=true;input.placeholder='Describe a step';input.value=value;input.setAttribute('aria-label','Workflow step');
 const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','Remove step');remove.onclick=()=>{if(document.querySelectorAll('.builder-step').length>1)row.remove()};
 row.append(input,remove);document.querySelector('#builder-steps').append(row);
}
function openWorkflowBuilder(goal){
 document.querySelector('#builder-form').reset();document.querySelector('#builder-goal').value=goal;
 document.querySelector('#builder-steps').replaceChildren();addBuilderStep();builder.showModal();
}
document.querySelector('#add-step').onclick=()=>addBuilderStep();
document.querySelector('.builder-close').onclick=()=>builder.close();
document.querySelector('#builder-form').onsubmit=e=>{
 e.preventDefault();
 const name=document.querySelector('#builder-name').value.trim(),goal=document.querySelector('#builder-goal').value.trim(),output=document.querySelector('#builder-output').value.trim();
 const steps=[...document.querySelectorAll('.builder-step input')].map(x=>x.value.trim()).filter(Boolean);
 if(!name||!goal||!output||!steps.length)return;
 const w=[name,'Custom',goal,output,'Your custom workflow inputs.',steps];
 try{localStorage.setItem('runable-custom-workflows',JSON.stringify([...savedWorkflows,w]));}catch{alert('This browser could not save the workflow. Please keep a copy of your steps.');return}
 savedWorkflows.push(w);workflows.push(w);builder.close();category='Custom';query='';document.querySelector('#search').value='';
 document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x.dataset.filter==='Custom');x.setAttribute('aria-pressed',String(x.dataset.filter==='Custom'))});render();document.querySelector('#library').scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth'});
};
// Reveal whole connections and activate nodes when the drawing reaches them.
const nodeMotion = [];
function animateWorkflowNodes(){
 nodeMotion.forEach(a=>a.cancel());nodeMotion.length=0;
 if(reducedMotion.matches)return;
 const paths=[...document.querySelectorAll('.wf-node-flow')];
 const cycle=14000,draw=4200;
 const branchStarts=[5050,4700,5750,5400,6450,6100,7150,6800];
 const startAt=index=>index<8?500+index*350:branchStarts[index-8];
 const drawAt=index=>index<8?draw:3000;
 // Invert ease-out's distance curve to keep node activation aligned with the tip.
 const timeAtDistance=fraction=>{
  let lo=0,hi=1;
  for(let i=0;i<24;i++){
   const t=(lo+hi)/2,y=3*t*t-2*t*t*t;
   if(y<fraction)lo=t;else hi=t;
  }
  const t=(lo+hi)/2;
  return 3*(1-t)*t*t*.58+t*t*t;
 };
 paths.forEach((path,index)=>{
  const start=startAt(index),pathDraw=drawAt(index);
  const frames=[{offset:0,strokeDashoffset:1,opacity:0},{offset:start/cycle,strokeDashoffset:1,opacity:0},{offset:(start+100)/cycle,strokeDashoffset:1,opacity:1,easing:'ease-out'},{offset:(start+pathDraw)/cycle,strokeDashoffset:0,opacity:1},{offset:.8,strokeDashoffset:0,opacity:1},{offset:.845,strokeDashoffset:0,opacity:0},{offset:1,strokeDashoffset:0,opacity:0}];
  [path,path.previousElementSibling].forEach(el=>nodeMotion.push(el.animate(frames,{duration:cycle,iterations:Infinity,easing:'linear'})));
 });
 document.querySelectorAll('.wf-tiny-node').forEach(node=>{
  const ring=node.querySelector('circle'),dot=node.querySelector('.wf-node-dot');
  const x=Number(dot.getAttribute('cx')),y=Number(dot.getAttribute('cy'));
  let nearest=Infinity,arrival=1000;
  paths.forEach((path,index)=>{
   const length=path.getTotalLength();
   for(let n=0;n<=240;n++){
    const fraction=n/240,p=path.getPointAtLength(length*fraction),distance=Math.hypot(p.x-x,p.y-y);
    const time=startAt(index)+100+(drawAt(index)-100)*timeAtDistance(fraction);
    if(distance<nearest-.2 || (Math.abs(distance-nearest)<.2&&time<arrival)){nearest=distance;arrival=time}
   }
  });
  const at=Math.min(arrival/cycle,.7);
  nodeMotion.push(dot.animate([{offset:0,opacity:0},{offset:at,opacity:0},{offset:at+.025,opacity:1},{offset:.8,opacity:1},{offset:.845,opacity:0},{offset:1,opacity:0}],{duration:cycle,iterations:Infinity,easing:'linear'}));
  nodeMotion.push(ring.animate([{offset:0,fill:'#858585',opacity:0},{offset:at,fill:'#858585',opacity:0},{offset:at+.025,fill:'#858585',opacity:1},{offset:.8,fill:'#858585',opacity:1},{offset:.845,fill:'#858585',opacity:0},{offset:1,fill:'#858585',opacity:0}],{duration:cycle,iterations:Infinity,easing:'linear'}));
 });
}
animateWorkflowNodes();reducedMotion.addEventListener('change',animateWorkflowNodes);
document.addEventListener('visibilitychange',()=>nodeMotion.forEach(a=>document.hidden?a.pause():a.play()));

document.querySelector('#create-workflow').addEventListener('click',()=>openWorkflowBuilder(''));
